/**
 * Cross-language vectors (PRD S1): LSAG signatures generated by the Solidity
 * reference (contracts/test/lib/SolLSAG.sol via ExportVectors.sol) must be
 * reproduced and verified by the TypeScript client bit-for-bit.
 */
import { readFileSync, existsSync, readdirSync } from 'fs';
import { join } from 'path';
import { lsagVerify, hpForRing, keyImage, lsagSign } from '../src/v2/crypto/lsag';
import { decodeUnchecked } from '../src/v2/crypto/bn254';

const VEC_DIR = join(__dirname, '../../contracts/vectors');

interface Case {
  t: number;
  mHash: string;
  ring: string[];
  c1: string;
  s: string[];
  I: string;
  secret: string;
  pi: number;
}

function loadCases(): Case[] {
  if (!existsSync(VEC_DIR)) return [];
  return readdirSync(VEC_DIR)
    .filter((f) => f.startsWith('case_') && f.endsWith('.json'))
    .sort((a, b) => Number(a.match(/\d+/)![0]) - Number(b.match(/\d+/)![0]))
    .map((f) => JSON.parse(readFileSync(join(VEC_DIR, f), 'utf8')));
}

function bytes(hex: string): Uint8Array {
  return new Uint8Array(Buffer.from(hex.slice(2), 'hex'));
}

describe('LSAG cross-language vectors (S1)', () => {
  const cases = loadCases();

  test('vector files exist (exporter ran)', () => {
    expect(cases.length).toBeGreaterThan(0);
  });

  for (const c of cases) {
    test(`case ${c.t}: TS verifies the Solidity signature`, () => {
      const ring = c.ring.map(bytes);
      const hp = hpForRing(ring);
      const I = bytes(c.I);
      const flat: string[] = Array.isArray(c.s[0]) ? (c.s as string[][]).flat() : (c.s as string[]);
      const s = flat.map((x) => BigInt(x));
      const m = bytes(c.mHash);
      expect(lsagVerify(m, ring, hp, I, c.c1, s)).toBe(true);
    });

    test(`case ${c.t}: TS key image matches Solidity`, () => {
      const ringBytes = c.ring.map(bytes);
      const mine = keyImage(BigInt(c.secret), ringBytes[c.pi]);
      expect(Buffer.from(mine).toString('hex')).toBe(c.I.slice(2));
      expect(decodeUnchecked(mine)).toBeDefined();
    });

    test(`case ${c.t}: TS verifies its own signature`, () => {
      const ringBytes = c.ring.map(bytes);
      const sig = lsagSign(bytes(c.mHash), ringBytes, c.pi, BigInt(c.secret));
      const hp = hpForRing(ringBytes);
      expect(lsagVerify(bytes(c.mHash), ringBytes, hp, sig.I, sig.c1, sig.s)).toBe(true);
    });

    test(`case ${c.t}: TS sign reproduces Solidity c1`, () => {
      const ringBytes = c.ring.map(bytes);
      const sig = lsagSign(bytes(c.mHash), ringBytes, c.pi, BigInt(c.secret));
      const flat: string[] = Array.isArray(c.s[0]) ? (c.s as string[][]).flat() : (c.s as string[]);
      // random-forced s values must match exactly (deterministic seed)
      for (let k = 0; k < flat.length; k++) {
        if (k === c.pi) continue;
        expect(sig.s[k]).toBe(BigInt(flat[k]));
      }
      expect(BigInt(sig.c1)).toBe(BigInt(c.c1));
    });
  }
});
